// ==========================================================================
// Motor de preferencias en lenguaje natural
// Puerto a JavaScript de la funcion Oracle "func.py" (translate_preferences).
// Corre 100% en el navegador: no hay backend ni base de datos.
// ==========================================================================

const BASE_WEIGHTS_DEFAULTS = {
    "Accesibilidad_Transporte_Publico": 0.10,
    "Accesibilidad_Gasolinera": 0,
    "Accesibilidad_Hospital": 0.10,
    "Accesibilidad_Salud_Basica": 0.05,
    "Accesibilidad_Servicios_Sociales_Para_Mayores": 0,
    "Accesibilidad_Farmacia": 0,
    "Accesibilidad_Hipermercado": 0.01,
    "Accesibilidad_Centro_Comercial": 0.01,
    "Accesibilidad_Comercio_Minorista": 0.10,
    "Accesibilidad_Mercado": 0.02,
    "Agradabilidad_Entorno": 0.07,
    "Accesibilidad_Educacion_Infantil": 0.01,
    "Accesibilidad_Educacion_Primaria": 0.01,
    "Accesibilidad_Educacion_Secundaria": 0.01,
    "Accesibilidad_Universidad": 0.01,
    "Accesibilidad_Ocio_Cultura": 0.02
    // TOTAL = 0.60, igual que en el original
};

const WEIGHT_KEYWORDS = new Map([
    ["mucho", 0.35], ["prioritario", 0.35], ["esencial", 0.35], ["fundamental", 0.35],
    ["imprescindible", 0.40], ["obligatorio", 0.35], ["vital", 0.35], ["maxima", 0.35],
    ["valoro_mucho", 0.40], ["necesito", 0.35],
    ["valoro", 0.20], ["importante", 0.20], ["deseo", 0.20], ["aprecio", 0.25],
    ["quiero", 0.30], ["prefiero", 0.25], ["conveniente", 0.20], ["muy", 0.20],
    ["cerca", 0.20], ["bueno", 0.10], ["debo", 0.10], ["proximo", 0.10],
    ["asequible", 0.15], ["accesible", 0.15], ["útil", 0.10]
]);

const NEUTRAL_KEYWORDS = new Map([
    ["no_importa", -0.20], ["no_me_importa", -0.20], ["no_nos_importa", -0.20],
    ["indiferente", -0.10], ["secundario", -0.10], ["bajo", -0.15],
    ["poco", -0.10], ["sin", -0.15], ["irrelevante", -0.15], ["tolerable", -0.10],
    ["da_igual", -0.20], ["escaso", -0.15], ["mínimo", -0.10],
    ["no_quiero", -0.30], ["prohibido", -0.35], ["evitar", -0.30],
    ["evito", -0.30], ["lejos", -0.40], ["odio", -0.40]
]);

const CRITERIA_MAP = [
    [["transporte", "metro", "bus", "renfe", "estacion", "cercanias", "interurbano", "publico"], "Accesibilidad_Transporte_Publico"],
    [["gasolinera", "gas", "petroleo", "carro"], "Accesibilidad_Gasolinera"],
    [["hospital", "urgencia", "urgencias", "hospitales", "enfermedad", "cirugia"], "Accesibilidad_Hospital"],
    [["centro_de_salud", "consultorio", "cita_medica", "vacuna", "chequeo", "enfermeria", "pediatria", "medico_de_cabecera", "control", "prevencion", "ambulatorio"], "Accesibilidad_Salud_Basica"],
    [["residencia", "centro_de_dia", "tercera_edad", "geriatria", "viejo", "anciano", "adulto_mayor", "abuelo", "abuela", "abuelos"], "Accesibilidad_Servicios_Sociales_Para_Mayores"],
    [["farmacia", "medicamento", "medicamentos", "receta", "farmaceutico"], "Accesibilidad_Farmacia"],
    [["verde", "parque", "parques", "arboles", "aire", "naturaleza"], "Agradabilidad_Entorno"],
    [["mercado", "mercadillo", "galeria", "alimentacion", "comercio", "tiendas"], "Accesibilidad_Mercado"],
    [["hipermercado"], "Accesibilidad_Hipermercado"],
    [["centro_comercial"], "Accesibilidad_Centro_Comercial"],
    [["comercio", "supermercado", "mercadona", "aldi", "carrefour", "lidl", "minorista"], "Accesibilidad_Comercio_Minorista"],
    [["infante", "guarderia", "escuela_infantil", "3_años", "2_años", "4_años", "5_años", "6_años", "desarrollo_temprano", "patio_infantil", "estimulacion", "cuidador"], "Accesibilidad_Educacion_Infantil"],
    [["primaria", "colegio", "escuela", "7_años", "8_años", "9_años", "10_años", "11_años", "12_años", "aula", "tutor", "asignaturas_primaria", "recreo"], "Accesibilidad_Educacion_Primaria"],
    [["secundaria", "instituto", "eso", "13_años", "14_años", "15_años", "16_años", "17_años", "18_años", "bachillerato", "examen", "orientador_academico", "optativas", "laboratorio", "TICS_educacion", "bullying", "FP", "formacion_profesional", "tutor_secundaria"], "Accesibilidad_Educacion_Secundaria"],
    [["universidad", "campus", "carrera", "grado", "master", "facultad", "beca_estudio", "biblioteca_universitaria", "investigacion", "tesis", "ERASMUS", "matricula", "creditos_ECTS"], "Accesibilidad_Universidad"],
    [["libreria", "museo", "teatro", "cine", "librerias", "museos", "teatros", "cines", "pelicula", "arte"], "Accesibilidad_Ocio_Cultura"],
    [["ocio", "restaurantes", "bares", "cine", "gimnasio", "gym", "vida social", "salir", "deporte"], "Ocio_Restauracion"]
];

const STOP_WORDS = new Set(["el", "la", "los", "las", "un", "una", "unos", "unas", "y", "o", "de", "del", "a", "en", "con", "por", "para"]);

const RESTRICTION_PATTERNS = [
    { type: "Price_Range", pattern: /(entre)\s*([\d.]+)\s*(y|e)\s*([\d.]+)\s*(euros|€)?/g },
    { type: "Price_Max", pattern: /(maximo|max|menos\s+de|no\s+mas\s+de|hasta)\s*([\d.]+)\s*(euros|€)?/g },
    { type: "Price_Min", pattern: /(minimo|min|mas\s+de|desde)\s*([\d.]+)\s*(euros|€)?/g },
    { type: "Time_Max", pattern: /(a|maximo|max|menos\s+de|hasta)\s*(\d+)\s*(minuto|min)s?/g },
    { type: "Distance_Max", pattern: /(a|maximo|max|menos\s+de|hasta)\s*(\d+)\s*(km|kilometros)/g }
];

function eliminarTildes(texto) {
    return texto.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function limpiarNumero(text) {
    return parseInt(text.replaceAll('.', '').replaceAll(',', ''), 10);
}

function buildWordToCriteria() {
    const map = new Map();
    for (const [keys, criteria] of CRITERIA_MAP) {
        for (const key of keys) map.set(key, criteria);
    }
    // Destinos que se usan solo para restricciones (tiempo/distancia), no son capas del mapa.
    map.set("trabajo", "Accesibilidad_Trabajo");
    map.set("curro", "Accesibilidad_Trabajo");
    map.set("oficina", "Accesibilidad_Trabajo");
    return map;
}

function extractRestrictions(cleanedText, wordToCriteria) {
    const restrictions = {};
    for (const { type, pattern } of RESTRICTION_PATTERNS) {
        pattern.lastIndex = 0;
        let match;
        while ((match = pattern.exec(cleanedText)) !== null) {
            if (type.startsWith('Price')) {
                const key = 'Precio_Vivienda';
                if (!restrictions[key]) restrictions[key] = {};
                if (type === 'Price_Range') {
                    restrictions[key].Valor_Min = limpiarNumero(match[2]);
                    restrictions[key].Valor_Max = limpiarNumero(match[4]);
                } else if (type === 'Price_Max') {
                    restrictions[key].Valor_Max = limpiarNumero(match[2]);
                } else if (type === 'Price_Min') {
                    restrictions[key].Valor_Min = limpiarNumero(match[2]);
                }
            } else {
                const windowStart = Math.max(0, match.index - 40);
                const windowEnd = Math.min(cleanedText.length, match.index + match[0].length + 40);
                const contextText = cleanedText.slice(windowStart, windowEnd);
                let targetKey = null;
                for (const word of contextText.split(/\s+/)) {
                    if (wordToCriteria.has(word)) { targetKey = wordToCriteria.get(word); break; }
                }
                if (targetKey) {
                    restrictions[targetKey] = { Tipo: type, Valor: parseInt(match[2], 10) };
                }
            }
        }
    }
    return restrictions;
}

function translatePreferences(preferenceText) {
    let cleanedText = eliminarTildes(preferenceText || '').replace(/[^\w\s]/g, '').toLowerCase();
    cleanedText = cleanedText.replaceAll('ñ', 'n');
    cleanedText = cleanedText.replaceAll('centro comercial', 'centro_comercial');
    cleanedText = cleanedText.replaceAll('no me importa', 'no_me_importa');
    cleanedText = cleanedText.replaceAll('no nos importa', 'no_nos_importa');
    cleanedText = cleanedText.replaceAll('no importa', 'no_importa');
    cleanedText = cleanedText.replaceAll('da igual', 'da_igual');
    cleanedText = cleanedText.replaceAll('no quiero', 'no_quiero');
    cleanedText = cleanedText.replaceAll('no tengo coche', 'no_tengo_coche');
    cleanedText = cleanedText.replaceAll('sin coche', 'no_tengo_coche');
    cleanedText = cleanedText.replaceAll('valoro mucho', 'valoro_mucho');
    cleanedText = cleanedText.replaceAll('centro de salud', 'centro_de_salud');
    cleanedText = cleanedText.replaceAll('cita medica', 'cita_medica');
    cleanedText = cleanedText.replaceAll('medico de cabecera', 'medico_de_cabecera');
    cleanedText = cleanedText.replaceAll('adulto mayor', 'adulto_mayor');
    cleanedText = cleanedText.replaceAll('tercera edad', 'tercera_edad');
    cleanedText = cleanedText.replaceAll('centro de dia', 'centro_de_dia');
    cleanedText = cleanedText.replaceAll('escuela infantil', 'escuela_infantil');
    cleanedText = cleanedText.replaceAll('desarrollo temprano', 'desarrollo_temprano');
    cleanedText = cleanedText.replaceAll('vivo sin mis abuelos', 'no_tengo_abuelos');
    cleanedText = cleanedText.replaceAll('vivo sin abuelos', 'no_tengo_abuelos');
    cleanedText = cleanedText.replaceAll('vivo sin mi abuelo', 'no_tengo_abuelos');
    cleanedText = cleanedText.replaceAll('vivo sin abuelo', 'no_tengo_abuelos');
    cleanedText = cleanedText.replaceAll('vivo sin personas mayores', 'no_tengo_abuelos');
    cleanedText = cleanedText.replaceAll('patio infantil', 'infante');
    cleanedText = cleanedText.replaceAll('asignaturas primaria', 'primaria');
    cleanedText = cleanedText.replaceAll('orientador academico', 'secundaria');
    cleanedText = cleanedText.replaceAll('creditos ECTS', 'universidad');
    cleanedText = cleanedText.replaceAll('biblioteca universitaria', 'universidad');
    cleanedText = cleanedText.replaceAll('beca estudio', 'universidad');

    cleanedText = cleanedText.replace(/\b(0|1|2|3|4|5|6)\s*an?i?os?\b/g, 'infante');
    cleanedText = cleanedText.replace(/\b(patio infantil|guarderia)\b/g, 'infante');
    cleanedText = cleanedText.replace(/\b(7|8|9|10|11|12)\s*an?i?os?\b/g, 'primaria');
    cleanedText = cleanedText.replace(/\b(13|14|15|16|17|18)\s*an?i?os?\b/g, 'secundaria');

    const words = cleanedText.split(/\s+/).filter(w => w.length > 0 && !STOP_WORDS.has(w));

    const contexto = {};
    // Copia local (a diferencia del original, que mutaba un dict global BASE_WEIGHTS
    // entre peticiones - un bug real en Oracle Fn porque los contenedores se reusan).
    const weights = Object.assign({}, BASE_WEIGHTS_DEFAULTS);

    const hasCarPositiveKeywords = ["coche", "auto", "vehiculo", "garaje", "parking", "aparcar"];
    const hasPresenceOldPeople = ["adulto_mayor", "tercera_edad", "anciano", "viejo", "abuelo", "abuela", "abuelos"];
    const hasPresenceKids = ["niños", "niñas", "niño", "niña", "infante"];
    const hasPresencePrimary = ["primaria", "colegio", "escuela"];
    const hasPresenceHighschool = ["joven", "secundaria", "instituto"];
    const hasPresenceCollege = ["adulto", "universidad", "campus", "carrera", "grado", "master", "facultad", "beca_estudio", "investigacion", "tesis", "ERASMUS", "matricula"];

    contexto.Tiene_Coche = false;
    for (const word of words) {
        if (hasCarPositiveKeywords.includes(word)) { contexto.Tiene_Coche = true; weights.Accesibilidad_Gasolinera = 0.1; break; }
        if (word === 'no_tengo_coche') { contexto.Tiene_Coche = false; break; }
    }

    contexto.Presencia_Adulto_Mayor = false;
    for (const word of words) {
        if (hasPresenceOldPeople.includes(word)) {
            contexto.Presencia_Adulto_Mayor = true;
            weights.Accesibilidad_Servicios_Sociales_Para_Mayores = 0.13;
            weights.Accesibilidad_Farmacia = 0.13;
            break;
        }
        if (word === 'no_tengo_abuelos') { contexto.Presencia_Adulto_Mayor = false; break; }
    }

    if (words.some(w => hasPresenceKids.includes(w))) weights.Accesibilidad_Educacion_Infantil = 0.13;
    if (words.some(w => hasPresencePrimary.includes(w))) weights.Accesibilidad_Educacion_Primaria = 0.13;
    if (words.some(w => hasPresenceHighschool.includes(w))) weights.Accesibilidad_Educacion_Secundaria = 0.13;
    if (words.some(w => hasPresenceCollege.includes(w))) weights.Accesibilidad_Universidad = 0.13;

    const dynamicWeights = {};
    for (const key in BASE_WEIGHTS_DEFAULTS) dynamicWeights[key] = 0.0;

    const wordToCriteria = buildWordToCriteria();

    // Boost (palabras de intensidad: "mucho", "valoro", "cerca"...)
    for (let i = 0; i < words.length; i++) {
        const word = words[i];
        if (!WEIGHT_KEYWORDS.has(word)) continue;
        const boost = WEIGHT_KEYWORDS.get(word);
        let targetFound = false;
        for (let j = i + 1; j < Math.min(words.length, i + 6); j++) {
            if (wordToCriteria.has(words[j])) {
                const criteria = wordToCriteria.get(words[j]);
                if (criteria in dynamicWeights) dynamicWeights[criteria] += boost;
                targetFound = true;
                break;
            }
        }
        if (!targetFound) {
            for (let j = Math.max(0, i - 3); j < i; j++) {
                if (wordToCriteria.has(words[j])) {
                    const criteria = wordToCriteria.get(words[j]);
                    if (criteria in dynamicWeights) dynamicWeights[criteria] += boost;
                    break;
                }
            }
        }
    }

    // Reduccion (palabras de indiferencia/negacion: "no me importa", "lejos"...)
    for (let i = 0; i < words.length; i++) {
        const word = words[i];
        if (!NEUTRAL_KEYWORDS.has(word)) continue;
        const reduction = NEUTRAL_KEYWORDS.get(word);
        let targetFound = false;
        for (let j = i + 1; j < Math.min(words.length, i + 5); j++) {
            if (wordToCriteria.has(words[j])) {
                const criteria = wordToCriteria.get(words[j]);
                if (criteria in dynamicWeights) dynamicWeights[criteria] += reduction;
                targetFound = true;
                break;
            }
        }
        if (!targetFound) {
            for (let j = Math.max(0, i - 3); j < i; j++) {
                if (wordToCriteria.has(words[j])) {
                    const criteria = wordToCriteria.get(words[j]);
                    if (criteria in dynamicWeights) dynamicWeights[criteria] += reduction;
                    break;
                }
            }
        }
    }

    const totalBoost = Object.values(dynamicWeights).reduce((a, b) => a + b, 0);
    if (totalBoost > 0.45) {
        const factor = 0.45 / totalBoost;
        for (const k in dynamicWeights) dynamicWeights[k] *= factor;
    }

    let finalWeights = {};
    for (const k in weights) finalWeights[k] = weights[k] + dynamicWeights[k];

    let totalSum = Object.values(finalWeights).reduce((a, b) => a + b, 0);
    if (totalSum > 0) for (const k in finalWeights) finalWeights[k] /= totalSum;

    // Peso minimo 0.001 y renormalizacion final
    for (const k in finalWeights) finalWeights[k] = Math.max(0.001, finalWeights[k]);
    totalSum = Object.values(finalWeights).reduce((a, b) => a + b, 0);
    if (totalSum > 0) for (const k in finalWeights) finalWeights[k] /= totalSum;

    const restrictions = extractRestrictions(cleanedText, wordToCriteria);

    return { Pesos: finalWeights, Restricciones: restrictions, Contexto_Usuario: contexto };
}

// ==========================================================================
// Calculo del indice de idoneidad (SP_INDEX) - antes era SQL sobre Oracle ADB,
// ahora recalcula en el navegador sobre el GeoJSON estatico data/municipios.geojson.
// ==========================================================================

// Municipios excluidos de la capa base (mismo filtro CMUN4 que la consulta original).
const EXCLUDED_CMUN4 = new Set([9036, 1132, 455, 148, 133, 225, 474, 800, 493, 1610, 1150, 1343, 1277, 1230, 66, 1065, 1489, 72, 650, 587, 745, 53, 920, 796]);

let rawFeatures = [];

async function loadAccessibilityData() {
    try {
        const res = await fetch('data/municipios.geojson');
        if (!res.ok) throw new Error('No se pudo cargar data/municipios.geojson (HTTP ' + res.status + ')');
        const data = await res.json();
        rawFeatures = (data.features || []).filter(f => {
            const cmun4 = f.properties ? Number(f.properties.CMUN4) : NaN;
            return !EXCLUDED_CMUN4.has(cmun4);
        });
    } catch (error) {
        console.error('Error cargando el dataset de accesibilidad:', error);
    }
}
const dataReady = loadAccessibilityData();

function computeSpIndex(props, pesos, tieneCoche) {
    const suf = tieneCoche ? '_COCHE' : '';
    const peso = (key, fallback) => (pesos && pesos[key] !== undefined) ? pesos[key] : fallback;
    const col = (base) => {
        const v = props[base + suf];
        return typeof v === 'number' ? v : 0;
    };

    return (
        (typeof props.ACCESIBILIDAD_TRANSPORTE === 'number' ? props.ACCESIBILIDAD_TRANSPORTE : 0) * peso('Accesibilidad_Transporte_Publico', 0.20) +
        col('ACCESIBILIDAD_HOSPITAL') * peso('Accesibilidad_Hospital', 0.25) +
        col('ACCESIBILIDAD_HIPERMERCADO') * peso('Accesibilidad_Hipermercado', 0.05) +
        col('ACCESIBILIDAD_COM_MINORISTA') * peso('Accesibilidad_Comercio_Minorista', 0.30) +
        col('ACCESIBILIDAD_MERCADO') * peso('Accesibilidad_Mercado', 0.05) +
        col('ACCESIBILIDAD_CENTROCOM') * peso('Accesibilidad_Centro_Comercial', 0.05) +
        col('ACCESIBILIDAD_SALUD_BASICA') * peso('Accesibilidad_Salud_Basica', 0.10) +
        col('ACCESIBILIDAD_SSOCIALES_MAYORES') * peso('Accesibilidad_Servicios_Sociales_Para_Mayores', 0) +
        col('ACCESIBILIDAD_FARMACIAS') * peso('Accesibilidad_Farmacia', 0) +
        col('ACCESIBILIDAD_EDUCACION_INFANTIL') * peso('Accesibilidad_Educacion_Infantil', 0.01) +
        col('ACCESIBILIDAD_EDUCACION_PRIMARIA') * peso('Accesibilidad_Educacion_Primaria', 0.01) +
        col('ACCESIBILIDAD_EDUCACION_SECUNDARIA') * peso('Accesibilidad_Educacion_Secundaria', 0.01) +
        col('ACCESIBILIDAD_UNIVERSIDAD') * peso('Accesibilidad_Universidad', 0.01) +
        (typeof props.ACCESIBILIDAD_OCIO_CULTURA === 'number' ? props.ACCESIBILIDAD_OCIO_CULTURA : 0) * peso('Accesibilidad_Ocio_Cultura', 0.01) +
        (typeof props.ACCESIBILIDAD_PARQUES === 'number' ? props.ACCESIBILIDAD_PARQUES : 0) * peso('Agradabilidad_Entorno', 0.01) +
        // Gasolineras siempre usan la columna en coche, igual que en la consulta SQL original.
        (typeof props.ACCESIBILIDAD_GASOLINERAS_COCHE === 'number' ? props.ACCESIBILIDAD_GASOLINERAS_COCHE : 0) * peso('Accesibilidad_Gasolinera', 0)
    );
}

function buildWeightedGeoJSON(pesos, tieneCoche) {
    const features = rawFeatures.map(f => ({
        type: 'Feature',
        geometry: f.geometry,
        properties: Object.assign({}, f.properties, { SP_INDEX: computeSpIndex(f.properties, pesos, !!tieneCoche) })
    }));
    features.sort((a, b) => b.properties.SP_INDEX - a.properties.SP_INDEX);
    return { type: 'FeatureCollection', features };
}

