    // --- Variables globales ---
    var geoJsonLayer = null;
    let lastComputedGeoJSON = null;
    var idToLayer = {}; 

    // --- Mapa ---
    var map = L.map('map').setView([40.4167, -3.70325], 10); 
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
        attribution: '&copy; <a href="http://www.openstreetmap.org/copyright">OpenStreetMap</a>'
    }).addTo(map);

    // Cerrar menús al clicar en el mapa
    map.on('click', () => {
        sidebar.classList.remove('active');
        sidebarRight.classList.remove('active');
    });

    // --- Estilos y Popups ---
    function lerpColor(a, b, t) {
        function hexToRgb(hex) { var bigint = parseInt(hex.slice(1), 16); return { r: (bigint >> 16) & 255, g: (bigint >> 8) & 255, b: bigint & 255 }; }
        function rgbToHex(r, g, b) { return '#' + (1 << 24 | r << 16 | g << 8 | b).toString(16).slice(1).toUpperCase(); }
        var colorA = hexToRgb(a); var colorB = hexToRgb(b);
        var r = Math.round(colorA.r + (colorB.r - colorA.r) * t);
        var g = Math.round(colorA.g + (colorB.g - colorA.g) * t);
        var b = Math.round(colorA.b + (colorB.b - colorA.b) * t);
        return rgbToHex(r, g, b);
    }
    const COLOR_ROJO_HIGH = '#D73027'; 
    const COLOR_AMARILLO_HIGH = '#FFFFBF'; 
    const COLOR_VERDE_HIGH = '#1A9850'; 

    function getColor(d) {
        d = Math.min(5, Math.max(1, d));
        if (d <= 3) { return lerpColor(COLOR_ROJO_HIGH, COLOR_AMARILLO_HIGH, (d - 1) / 2); }
        else { return lerpColor(COLOR_AMARILLO_HIGH, COLOR_VERDE_HIGH, (d - 3) / 2); }
    }

    function style(feature) {
        return { fillColor: getColor(feature.properties.SP_INDEX), weight: 0, opacity: 1, color: 'white', dashArray: '', fillOpacity: 0.6 };
    }

    function onEachFeature(feature, layer) {
        if (feature.properties && feature.properties.SP_INDEX) {
            const percentage = ((feature.properties.SP_INDEX - 1) / 4) * 100;
            layer.bindPopup("<b>Municipalidad:</b> " + feature.properties.MUNICIPIO + "<br><b>Idoneidad:</b> " + percentage.toFixed(0) + "% (" + feature.properties.SP_INDEX.toFixed(2) + " de 5)");
            if (feature.properties.GRID_ID) idToLayer[feature.properties.GRID_ID] = layer;
        }
    }

    // Leyenda
    var legend = L.control({ position: 'bottomright' });
    legend.onAdd = function (map) {
        var div = L.DomUtil.create('div', 'ui-panel legend');
        var grades = [1, 2, 3, 4, 5]; 
        var labels = ['Mínima (1)', 'Baja (2)', 'Media (3)', 'Alta (4)', 'Óptima (5)'];
        div.innerHTML = '<h4>Leyenda</h4>';
        for (var i = 0; i < grades.length; i++) {
            div.innerHTML += '<i style="background:' + getColor(grades[i]) + '"></i> ' + labels[i] + '<br>';
        }
        L.DomEvent.disableClickPropagation(div);
        return div;
    };
    legend.addTo(map);

    // --- API ---
    sendButton.addEventListener('click', handleSubmit);
    chatInput.addEventListener('keypress', function(e) { if (e.key === 'Enter') handleSubmit(); });

    exportButton.addEventListener('click', function() {
        if (!lastComputedGeoJSON) { alert('Genera un mapa primero.'); return; }
        const blob = new Blob([JSON.stringify(lastComputedGeoJSON)], { type: 'application/geo+json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'madrid_idoneidad.geojson';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    });

    async function handleSubmit() {
        const preferenceText = chatInput.value.trim();
        if (preferenceText === "") return;
        showLoader(true); showError(null); 
        await fetchAndLoadGeoJSON(preferenceText);
    }

    async function fetchAndLoadGeoJSON(preferenceText) {
        try {
            await dataReady;
            if (rawFeatures.length === 0) throw new Error('El mapa base de accesibilidad no esta disponible todavia.');

            const analisis = translatePreferences(preferenceText);
            const analisisAplicado = {
                Pesos_Normalizados: analisis.Pesos,
                Restricciones_Aplicadas: analisis.Restricciones,
                Contexto_Adicional: analisis.Contexto_Usuario
            };
            updateInfoPanel(analisisAplicado);

            lastComputedGeoJSON = buildWeightedGeoJSON(analisis.Pesos, analisis.Contexto_Usuario.Tiene_Coche);
            updateMap(lastComputedGeoJSON);

        } catch (error) { handleApiError(error); } finally { showLoader(false); }
    }


    async function handleWeightUpdate() {
        showLoader(true);
        const sliders = document.querySelectorAll('.weight-slider');
        let rawWeights = {};
        let totalWeight = 0;
        sliders.forEach(slider => {
            const val = parseFloat(slider.value);
            rawWeights[slider.dataset.key] = val;
            totalWeight += val;
        });
        let normalizedWeights = {};
        if (totalWeight > 0) {
            for (const key in rawWeights) normalizedWeights[key] = rawWeights[key] / totalWeight;
        }
        await fetchAndLoadGeoJSON_withWeights(normalizedWeights);
        checkAndShowPOILayers();
    }

    async function fetchAndLoadGeoJSON_withWeights(weightsObject) {
        const carCh = document.getElementById('chk-context-coche');
        const oldCh = document.getElementById('chk-context-mayor');
        let currentContext = {};
        if (carCh) currentContext["Tiene_Coche"] = carCh.checked;
        if (oldCh) currentContext["Presencia_Adulto_Mayor"] = oldCh.checked;

        try {
            await dataReady;
            if (rawFeatures.length === 0) throw new Error('El mapa base de accesibilidad no esta disponible todavia.');

            lastComputedGeoJSON = buildWeightedGeoJSON(weightsObject, currentContext.Tiene_Coche);
            updateMap(lastComputedGeoJSON);

        } catch (error) { handleApiError(error); } finally { showLoader(false); }
    }


    // --- Actualizar Mapa y Lista ---
    function updateMap(geoJsonData) {
        if (!geoJsonData || !geoJsonData.type) return;
        if (geoJsonLayer) map.removeLayer(geoJsonLayer);
        idToLayer = {}; 

        geoJsonLayer = L.geoJSON(geoJsonData, {
            style: style,
            onEachFeature: onEachFeature
        }).addTo(map);
        
        if (geoJsonLayer.getBounds().isValid()) map.fitBounds(geoJsonLayer.getBounds());

        if (geoJsonData.features && geoJsonData.features.length > 0) {
            updateTop10List(geoJsonData.features);
        }
    }

    function updateTop10List(features) {
        top10List.innerHTML = '';
        
        // Mostrar panel en Desktop si hay datos
        if(window.innerWidth > 768) {
            sidebarRight.style.display = 'flex';
        }
        
        const top10 = features.slice(0, 10);
        top10.forEach((feature, index) => {
            const props = feature.properties;
            const scoreRaw = props.SP_INDEX ? props.SP_INDEX.toFixed(2) : "0.00";
            const percentage = props.SP_INDEX ? (((props.SP_INDEX - 1) / 4) * 100).toFixed(0) : 0;
            const id = props.GRID_ID || "N/A";
            const muni = props.MUNICIPIO || "N/A";
            
            const li = document.createElement('li');
            li.className = 'top10-item';
            li.innerHTML = `
                <div class="top10-header">
                    <span class="top10-rank">#${index + 1}</span>
                    <span class="top10-score">${percentage}%</span>
                </div>
                <div class="top10-id">Municipalidad: ${muni} <span style="color:#aaa;">(${scoreRaw}/5)</span></div>
            `;
            li.addEventListener('click', () => {
                const layer = idToLayer[id];
                if (layer) {
                    map.flyTo(layer.getBounds().getCenter(), 15);
                    layer.openPopup();
                    // Cerrar solo en móvil
                    if(window.innerWidth <= 768) sidebarRight.classList.remove('active');
                }
            });
            top10List.appendChild(li);
        });
    }

    function showLoader(show) { loader.style.display = show ? 'block' : 'none'; }
    function showError(message) { errorMessage.style.display = message ? 'block' : 'none'; errorMessage.innerHTML = message || ''; }
    function handleApiError(error) { showError("Error: " + error.message); console.error(error); }

    function updateInfoPanel(analisisData) {
        const contentDiv = document.getElementById('info-content');
        if (!contentDiv) return;
        let html = '';

        const definitions = {
            'Accesibilidad_Hospital': 'Cercanía a hospitales públicos y privados con servicio de urgencias.',
            'Accesibilidad_Salud_Basica': 'Proximidad a centros de salud (CS) y consultorios locales.',
            'Accesibilidad_Farmacia': 'Disponibilidad de farmacias en un radio caminable.',
            'Accesibilidad_Servicios_Sociales_Para_Mayores': 'Acceso a centros de día y residencias de tercera edad.',
            'Accesibilidad_Hipermercado': 'Grandes superficies de alimentación y productos varios.',
            'Accesibilidad_Centro_Comercial': 'Zonas con alta densidad de tiendas, moda y ocio comercial.',
            'Accesibilidad_Comercio_Minorista': 'Supermercados y pequeño comercio.',
            'Accesibilidad_Mercado': 'Mercados municipales de abastos y producto fresco.',
            'Accesibilidad_Transporte_Publico': 'Paradas de autobús y metro.',
            'Accesibilidad_Gasolinera': 'Estaciones de servicio para repostaje de vehículos.',
            'Accesibilidad_Ocio_Cultura': 'Cines, teatros, museos y librerías.',
            'Agradabilidad_Entorno': 'Zonas verdes y calidad del aire.',
            'Accesibilidad_Educacion_Infantil': 'Guarderías y escuelas infantiles (0-3 y 3-6 años).',
            'Accesibilidad_Educacion_Primaria': 'Colegios de educación primaria públicos y concertados.',
            'Accesibilidad_Educacion_Secundaria': 'Institutos de educación secundaria (ESO y Bachillerato).',
            'Accesibilidad_Universidad': 'Facultades y centros universitarios superiores.'
        };

        if (analisisData.Contexto_Adicional) {
            const ctx = analisisData.Contexto_Adicional;
            html += '<div class="context-box">';
            if (ctx.hasOwnProperty('Tiene_Coche')) html += `<div style="margin:5px 0;"><input type="checkbox" id="chk-context-coche" ${ctx.Tiene_Coche?'checked':''}><label for="chk-context-coche"> Tiene Coche</label></div>`;
            if (ctx.hasOwnProperty('Presencia_Adulto_Mayor')) html += `<input type="checkbox" id="chk-context-mayor" ${ctx.Presencia_Adulto_Mayor?'checked':''}><label for="chk-context-mayor"> Adulto Mayor</label>`;
            html += '</div><hr>';        
        }

        if (analisisData.Restricciones_Aplicadas) {
            const r = analisisData.Restricciones_Aplicadas;
            if (Object.keys(r).length > 0) {
                html += '<details><summary><strong>Restricciones Activas</strong></summary><ul style="margin-top:5px; color:#666;">';
                for(let k in r) html += `<li>${k.replace(/_/g, ' ')}</li>`;
                html += '</ul></details><hr>';
            }
        }

        if (analisisData.Pesos_Normalizados) {
            const p = analisisData.Pesos_Normalizados;
            const keys = Object.keys(p);

            if (keys.length > 0) {
                html += '<h4 style="margin-bottom:10px;">Ajusta tus Prioridades:</h4>';
                const categories = {
                    'Salud': ['Accesibilidad_Hospital', 'Accesibilidad_Salud_Basica', 'Accesibilidad_Farmacia','Accesibilidad_Servicios_Sociales_Para_Mayores'],
                    'Comercio': ['Accesibilidad_Hipermercado', 'Accesibilidad_Centro_Comercial', 'Accesibilidad_Comercio_Minorista', 'Accesibilidad_Mercado'],
                    'Transporte y Servicios': ['Accesibilidad_Transporte_Publico', 'Accesibilidad_Gasolinera', 'Accesibilidad_Ocio_Cultura', 'Agradabilidad Entorno'],
                    'Educacion': ['Accesibilidad_Educacion_Infantil','Accesibilidad_Educacion_Primaria','Accesibilidad_Educacion_Secundaria','Accesibilidad_Universidad']
                };

                // Calculo valores para mostrar
                let sliderValues = {};
                let tP = 0; 
                keys.forEach(k => { 
                    const v = parseFloat((p[k]*100).toFixed(0)); 
                    sliderValues[k] = v; 
                    tP+=v; 
                });
                // Ajuste de redondeo al último si no suma 100
                if(tP!==100 && keys.length>0) sliderValues[keys[keys.length-1]] += (100-tP);

                // Función auxiliar para crear el HTML de un slider
                const createSliderHTML = (key) => {
                    // Quitamos "Accesibilidad" y guiones bajos para que el texto sea limpio
                    const label = key.replace('Accesibilidad_', '').replace(/_/g, ' ');
                    const val = sliderValues[key];
                    const desc = definitions[key] || "Sin información adicional.";
                    return `
                        <div class="slider-item">
                            <div style="display:flex; justify-content:space-between; font-size:0.9em; margin-bottom:2px;">
                                <label for="slider-${key}">${label}</label>
                                <div class="tooltip-container">
                                    <span class="info-icon">i</span>
                                    <span class="tooltip-text">${desc}</span>
                                </div>
                                <span id="value-${key}" class="slider-value">${val}%</span>
                            </div>
                            <input type="range" id="slider-${key}" class="weight-slider" data-key="${key}" min="0" max="50" value="${val}" data-value-target="value-${key}" style="width:100%;">
                        </div>`;
                };

                // Renderizar por Categorías
                let usedKeys = [];
                
                for (const [catName, catKeys] of Object.entries(categories)) {
                    const validKeys = catKeys.filter(k => keys.includes(k));
                    
                    if (validKeys.length > 0) {
                        html += `<div class="category-group">
                                    <h5 style="margin: 8px 0 5px 0; color:#555; font-size:0.85em; text-transform:uppercase; border-bottom:1px solid #eee;">${catName}</h5>`;
                        validKeys.forEach(k => {
                            html += createSliderHTML(k);
                            usedKeys.push(k);
                        });
                        html += `</div>`;
                    }
                }

                // Renderizar los que sobraron (si la API devuelve algo nuevo)
                const remainingKeys = keys.filter(k => !usedKeys.includes(k));
                if (remainingKeys.length > 0) {
                    html += `<div class="category-group"><h5 style="margin: 8px 0 5px 0; color:#555;">Otros</h5>`;
                    remainingKeys.forEach(k => html += createSliderHTML(k));
                    html += `</div>`;
                }

                html += '<button id="updateWeightsButton">Recalcular Mapa</button>';
            }
        }
        html += '<hr style="margin:15px 0;"><details><summary><strong>Ver en el mapa</strong></summary><ul id="poi-toggles" style="list-style:none;padding:0;margin:5px 0;"></ul></details>';
        contentDiv.innerHTML = html;
        setupSlidersLogic(); setupCheckboxesLogic(); setupPOILogic();
    }
    
    function setupSlidersLogic() {
        const allSliders = Array.from(document.querySelectorAll('.weight-slider'));
        allSliders.forEach(slider => {
            slider.dataset.previousValue = slider.value;
            slider.addEventListener('input', (e) => handleSliderInput(e.target, allSliders));
        });
        const btn = document.getElementById('updateWeightsButton');
        if(btn) btn.addEventListener('click', handleWeightUpdate);
    }
    
    function setupCheckboxesLogic() {
        const carCh = document.getElementById('chk-context-coche');
        if(carCh) carCh.addEventListener('change', function() {
             const s = document.querySelector('.weight-slider[data-key="Accesibilidad_Transporte_Publico"]');
             if(s) { s.value = this.checked ? 0 : 30; handleSliderInput(s, Array.from(document.querySelectorAll('.weight-slider'))); }
        });

        const oldCh = document.getElementById('chk-context-mayor');
        if(oldCh) oldCh.addEventListener('change', function() {
            const s = document.querySelector('.weight-slider[data-key="Accesibilidad_Servicios_Sociales_Para_Mayores"]');
            const t = document.querySelector('.weight-slider[data-key="Accesibilidad_Farmacia"]');
            if(s) { s.value = this.checked ? 20 : 0; handleSliderInput(s, Array.from(document.querySelectorAll('.weight-slider'))); }
            if(t) { t.value = this.checked ? 20 : 0; handleSliderInput(t, Array.from(document.querySelectorAll('.weight-slider'))); }
        });
    }
    
    function setupPOILogic() {
        const list = document.getElementById('poi-toggles');
        if(!list) return;
        for(let layer in poiLayersManager) {
            const cfg = poiLayersManager[layer];
            const slider = document.querySelector(`.weight-slider[data-key="${cfg.sliderKey}"]`);
            if(slider) {
                const val = parseFloat(slider.value);
                cfg.isVisible = val > cfg.threshold;
                const li = document.createElement('li');
                li.innerHTML = `<input type="checkbox" class="poi-toggle" data-key="${layer}" ${cfg.isVisible?'checked':''}><label> ${layer}</label>`;
                list.appendChild(li);
            }
        }
        list.querySelectorAll('.poi-toggle').forEach(ch => {
            ch.addEventListener('change', (e) => {
                poiLayersManager[e.target.dataset.key].isVisible = e.target.checked;
                checkAndShowPOILayers();
            });
        });
        checkAndShowPOILayers();
    }

    function updateLabel(slider, value) {
        const t = document.getElementById(slider.dataset.valueTarget);
        if(t) t.textContent = Math.round(value) + '%';
    }

    function handleSliderInput(currentSlider, allSliders) {
        
        // --- CASO 1: 2 SLIDERS (Lógica simple) ---
        if (allSliders.length === 2) {
            const otherSlider = (allSliders[0] === currentSlider) ? allSliders[1] : allSliders[0];
            const newValue = 100 - parseInt(currentSlider.value, 10);
            
            otherSlider.value = newValue;
            
            // Actualizar etiquetas y valores "previos"
            updateLabel(currentSlider, currentSlider.value);
            updateLabel(otherSlider, otherSlider.value);
            currentSlider.dataset.previousValue = currentSlider.value;
            otherSlider.dataset.previousValue = otherSlider.value;
            return;
        }

        // --- CASO 2: 3+ SLIDERS (Lógica proporcional) ---
        if (allSliders.length > 2) {
            let currentValue = parseInt(currentSlider.value, 10);
            const prevValue = parseInt(currentSlider.dataset.previousValue, 10);
            let delta = currentValue - prevValue;

            if (delta === 0) return;

            // Encontrar los otros sliders y su valor total "disponible"
            const otherSliders = allSliders.filter(s => s !== currentSlider);
            let totalOfOthers = 0;
            otherSliders.forEach(s => {
                totalOfOthers += parseInt(s.dataset.previousValue, 10);
            });

            if (delta > 0 && delta > totalOfOthers) {
                delta = totalOfOthers;
                currentValue = prevValue + delta;
                currentSlider.value = currentValue; 
            }

            let deltaToDistribute = -delta;
            let totalChangeApplied = 0;
            let newValues = {}; // Almacén temporal

            // Distribuir el cambio entre los "otros", excepto el último
            for (let i = 0; i < otherSliders.length - 1; i++) {
                const other = otherSliders[i];
                const otherPrev = parseInt(other.dataset.previousValue, 10);
                
                // Distribuir proporcionalmente. Si todos son 0, distribuir equitativamente.
                const proportion = (totalOfOthers === 0) ? (1.0 / otherSliders.length) : (otherPrev / totalOfOthers);
                let change = deltaToDistribute * proportion; // Puede ser decimal

                // Asegurar que el cambio no lleve el slider bajo 0
                if (otherPrev + change < 0) {
                    change = -otherPrev;
                }

                newValues[other.id] = otherPrev + change; // Almacenar valor (puede ser decimal)
                totalChangeApplied += change;
            }

            // El último slider absorbe el "resto" para que la suma sea exacta
            const lastOther = otherSliders[otherSliders.length - 1];
            const lastOtherPrev = parseInt(lastOther.dataset.previousValue, 10);
            const lastChange = deltaToDistribute - totalChangeApplied;
            newValues[lastOther.id] = lastOtherPrev + lastChange;
            
            // APLICAR TODOS LOS CAMBIOS A LA VEZ
            allSliders.forEach(s => {
                let finalValue;
                if (s === currentSlider) {
                    finalValue = currentValue;
                } else {
                    finalValue = newValues[s.id];
                }

                // Doble chequeo de límites (0-100)
                if (finalValue < 0) finalValue = 0;
                if (finalValue > 100) finalValue = 100;

                s.value = finalValue; // Asignar valor 
                s.dataset.previousValue = finalValue;
                updateLabel(s, finalValue); // Actualizar etiqueta
            });
            
            // Re-redondear y ajustar suma final a 100
            let totalRounded = 0;
            
            // 1. Redondear todos menos el último y sumar
            for (let i = 0; i < allSliders.length - 1; i++) {
                const s = allSliders[i];
                const rounded = Math.round(parseFloat(s.value));
                s.value = rounded;
                s.dataset.previousValue = rounded;
                updateLabel(s, rounded);
                totalRounded += rounded;
            }
            
            // 2. Calcular lo que le toca al último
            const lastSlider = allSliders[allSliders.length - 1];
            let lastSliderNewValue = 100 - totalRounded;

            // --- PROTECCIÓN CONTRA NEGATIVOS ---
            if (lastSliderNewValue < 0) {
                const overflow = Math.abs(lastSliderNewValue);
                
                lastSliderNewValue = 0;

                if (currentSlider !== lastSlider) {
                    let currentVal = parseInt(currentSlider.value, 10);
                    let correctedVal = currentVal - overflow;
                    
                    // Asegurar que no baje de 0 tampoco
                    if(correctedVal < 0) correctedVal = 0;

                    currentSlider.value = correctedVal;
                    currentSlider.dataset.previousValue = correctedVal;
                    updateLabel(currentSlider, correctedVal);
                }
            }

            // 3. Aplicar el valor final al último slider
            lastSlider.value = lastSliderNewValue;
            lastSlider.dataset.previousValue = lastSliderNewValue;
            updateLabel(lastSlider, lastSliderNewValue);
        }
        
        // --- CASO 3: 1 SLIDER (Solo actualizar su valor) ---
        if (allSliders.length === 1) {
             currentSlider.dataset.previousValue = currentSlider.value;
             updateLabel(currentSlider, currentSlider.value);
        }
    }  

    function createGenericPOILayer(config) {
        if (!config.data || config.data.length === 0) return null;
        
        const features = config.data.map(item => {
            try { 
                return { 
                    type: "Feature", 
                    geometry: (config.geometryIsString ? JSON.parse(item.geometry) : item.geometry), 
                    properties: item.properties 
                }; 
            } catch(e) { return null; }
        }).filter(Boolean);

        const layer = L.geoJSON({type:"FeatureCollection", features:features}, {
            pointToLayer: (f, latlng) => L.marker(latlng, { icon: config.icon }),
            
            // --- SECCIÓN MODIFICADA PARA EL POPUP ---
            onEachFeature: (f, l) => { 
                let popupContent = "";
                
                // 1. 'popupKeys' 
                if (config.popupKeys && Array.isArray(config.popupKeys)) {
                    config.popupKeys.forEach(key => {
                        if (f.properties[key]) {
                            popupContent += `<b>${key}:</b> ${f.properties[key]}<br>`;
                        }
                    });
                } 
                else if (config.popupKey && f.properties[config.popupKey]) {
                    popupContent = `<b>${config.popupKey}:</b> ${f.properties[config.popupKey]}`;
                }

                if (popupContent) {
                    l.bindPopup(popupContent);
                }
            }
        });

        if (config.useClustering) {
            const g = L.markerClusterGroup({ maxClusterRadius: 70, disableClusteringAtZoom: 16 });
            g.addLayer(layer);
            return g;
        }
        return layer;
    }

    function checkAndShowPOILayers() {
        for (let name in poiLayersManager) {
            const cfg = poiLayersManager[name];
            if (cfg.isVisible) {
                if (!cfg.layerInstance) cfg.layerInstance = createGenericPOILayer(cfg);
                if (cfg.layerInstance && !map.hasLayer(cfg.layerInstance)) cfg.layerInstance.addTo(map);
            } else {
                if (cfg.layerInstance && map.hasLayer(cfg.layerInstance)) map.removeLayer(cfg.layerInstance);
            }
        }
    }
